class CreateJobDialogController{constructor($scope,$mdDialog,DispatchData,toastrService,$http,$document,dispatchJobService,staffId,despatcherName){this.$scope=$scope;this.$mdDialog=$mdDialog;this.DispatchData=DispatchData;this.$http=$http;this.toastrService=toastrService;this.$document=$document;this._staffId=staffId;this._despatcherName=despatcherName;this.dispatchJobService=dispatchJobService;this.addPalletForm=$scope.jobForm;this.fromAddressSearchText="";this.toAddressSearchText="";this.searchClientText="";this.courierSearchText="";this.isLoading=false;this.selectedCourier=null;this.selectedClient=null;this.selectedSpeed=null;console.log("staffId: ",staffId);console.log("despatcherName: ",despatcherName);this.speedOptions=[];DispatchData.getSpeedList().then(data=>{this.speedOptions=data});this.jobDate=new Date;this.job={clientID:"",courierId:null,deliverToContact:"",fromAddress:"",toAddress:"",date:"",fromContactName:"",podName:"",jobNotes:"",deliveryNotes:"",pickupNotes:"",van:false,truck:false,pedal:false,attention:false,vanOK:false,reprice:false,void:false,charge:0,refA:"",refB:""}}resetChoices(){this.job.van=false;this.job.truck=false;this.job.pedal=false;this.job.attention=false;this.job.vanOK=false;this.job.reprice=false;this.job.void=false}updateChoice(key){this.resetChoices();this.job[key]=true}async clientSearchAutocomplete(searchTerm){const url="/home/ActiveClients";try{return await this.DispatchData.autocompleteSearch(searchTerm,url)}catch(error){this.toastrService.showErrorToast(error.message)}}async courierSearch(searchText){try{const url="/courier/AllActiveSearch";return await this.DispatchData.autocompleteSearch(searchText,url)}catch(error){this.toastrService.showErrorToast(error.message)}}async addressSearchAutocomplete(searchText){try{const suggestions=await this.DispatchData.autocompleteAddressSearch(searchText);return this.transformSuggestions(suggestions)}catch(error){this.toastrService.showErrorToast(error.message)}}transformSuggestions(data){return data.suggestions.map(obj=>({id:obj.locationId,text:obj.label.split(", ").reverse().join(", ")}))}async findSuburbByDistrict(district){const ourSuburbs=await this.DispatchData.getSuburbList();let lowerCaseDistrict=district.toLowerCase();return ourSuburbs.find(localSuburb=>localSuburb.text.toLowerCase()===lowerCaseDistrict||localSuburb.alias&&localSuburb.alias.toLowerCase()===lowerCaseDistrict)}async addressSearchItemSelected(item,isToAddress){try{const data=await this.DispatchData.getGeoCodeInformation(item);const returnedLocation=data.Response.View[0].Result[0].Location;const lat=returnedLocation.DisplayPosition.Latitude;const long=returnedLocation.DisplayPosition.Longitude;const mappedSub=await this.findSuburbByDistrict(returnedLocation.Address.District);if(mappedSub!==undefined){this.assignAddressToJob(mappedSub.id,item.text,lat,long,isToAddress)}}catch(error){console.log("Error: ",error)}}assignAddressToJob(suburbId,addressFull,lat,long,toAddress){if(toAddress){this.job.toSuburb=suburbId;this.job.toAddress=addressFull;this.job.toLat=lat;this.job.toLong=long}else{this.job.fromSuburb=suburbId;this.job.fromAddress=addressFull;this.job.fromLat=lat;this.job.fromLong=long}}async submit(job){try{this.isLoading=true;if(!this.jobForm.$valid){this.toastrService.showWarningToast("Please complete all the required fields.");return}job.clientID=this.selectedClient.id;job.date=this.jobDate.toISOString();job.speedId=this.selectedSpeed.id;const response=await this._createJob(job);const jobId=response.data.jobId;if(this.selectedCourier){await this.dispatchJobService.dispatchJobByJobId(this.selectedCourier.id,jobId).then(()=>{this.$scope.selectJobDetail(job.id)})}this.$mdDialog.hide(jobId)}catch(error){this.toastrService.showErrorToast(error.message)}finally{this.isLoading=false}}async _createJob(job){const url="job/QuickCreateJob/";const callData={job:job,staffId:this._staffId,despatcherName:this._despatcherName};return await this.$http.post(url,callData,{headers:{"Content-Type":"application/json"}})}cancel(){this.$mdDialog.cancel()}}